/* Mon premier commentaire CSS */

h1, h2, p {
  text-align: center;
}

body {
  background-color: lightcyan;
  background-image: url('voyage.jpg');
}

.voyage {
  width: 80%;
  background-color: coral;
  margin-left: auto;
  margin-right: auto;
  padding-top: 20px;
  padding-right: 20px;
  padding-bottom: 20px;
  padding-left: 20px;
  max-width: 500px;
}

.voyage h1, .voyage h2 {
  font-family: sans-serif;
}

.voyage form {
  text-align: center;
}

